import{z as s,x as A,o as E,c as d,q as r,j as o,D as e,d as n,s as i,S as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"REST 检索投机","description":"","frontmatter":{"title":"REST 检索投机","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rest-spec.md","filePath":"llm/rest-spec.md","lastUpdated":1791413859000}'),B={name:"llm/rest-spec.md"};function p(h,a,T,m,c,S){const t=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=r('<h1 id="rest-检索投机" tabindex="-1">REST 检索投机 <a class="header-anchor" href="#rest-检索投机" aria-label="Permalink to &quot;REST 检索投机&quot;">​</a></h1><div class="epigraph"><p>不必再训一个草稿模型：用当前后缀去语料库做精确匹配，把检索到的续写收成 Trie，一次树注意力交给目标模型验证。</p><footer>—— He, Zhong, Cai, Lee, He，REST: Retrieval-Based Speculative Decoding，NAACL 2024</footer></div><p>投机要快，通常先养一个与目标同词表的小模型。<a href="/llm/draft-model">草稿选择</a> 本身就是一套运维。Zhenyu He、Zexuan Zhong、Tianle Cai、Jason D. Lee 与 Di He 的 REST（Retrieval-Based Speculative Decoding）把 \\(q\\) 换成<strong>非参数检索</strong>：预构建 datastore，推理时用已生成后缀做精确匹配，命中片段的后续 token 当作草稿。验证仍走目标模型一次前向，树注意力与 <a href="/llm/specinfer">SpecInfer</a> 同族。本篇写后缀数组、Trie 剪枝与适用域，不把 RAG 的语义检索说成 REST。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>参数化草稿有三笔账。训练要对齐目标分布；部署要占显存与调度槽；目标一升级，草稿往往要重蒸。<span class="marginnote">「非参数检索」翻译过来就是：知识不压进权重，而是把语料原样存成一张表，用的时候按字符串去查。参数化草稿像让一个小模型「背下」目标模型的写作习惯；REST 像直接抱着一本原文选集，写到哪就翻到哪页找「上一次别人在这里是怎么接的」。前者要花训练成本，后者的成本只在建索引和存磁盘。</span>很多生成轨迹其实高度重复：API 样板、Markdown 列表、单元测试骨架、客服话术。这些 n-gram 已经写在预训练或指令数据里，小模型只是在用参数记忆同一件事。REST 的问题是：若草稿的信息主要来自「语料里见过的续写」，能否跳过参数，直接查表？</p>',5)),(E(),o(l,null,{default:e(()=>[i(t,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20PARA%5B%22%E5%8F%82%E6%95%B0%E5%8C%96%E8%8D%89%E7%A8%BF%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20%20%20P1%5B%22%E8%AE%AD%E7%BB%83%E5%AF%B9%E9%BD%90%E7%9B%AE%E6%A0%87%E5%88%86%E5%B8%83%22%5D%20--%3E%20P2%5B%22%E5%B8%B8%E9%A9%BB%E6%98%BE%E5%AD%98%E4%B8%8E%E8%B0%83%E5%BA%A6%E6%A7%BD%22%5D%0A%20%20%20%20P2%20--%3E%20P3%5B%22%E7%9B%AE%E6%A0%87%E5%8D%87%E7%BA%A7%E9%9C%80%E9%87%8D%E8%92%B8%22%5D%0A%20%20end%0A%20%20subgraph%20REST2%5B%22REST%20%E6%A3%80%E7%B4%A2%E8%8D%89%E7%A8%BF%22%5D%0A%20%20%20%20R1%5B%22%E7%A6%BB%E7%BA%BF%E5%BB%BA%E5%90%8E%E7%BC%80%E7%B4%A2%E5%BC%95%22%5D%20--%3E%20R2%5B%22%E4%B8%8D%E5%8D%A0%20GPU%20%E8%8D%89%E7%A8%BF%E7%AE%97%E5%8A%9B%22%5D%0A%20%20%20%20R2%20--%3E%20R3%5B%22%E6%8D%A2%E5%88%86%E8%AF%8D%E5%99%A8%E6%89%8D%E9%9C%80%E9%87%8D%E5%BB%BA%22%5D%0A%20%20end%0A%20%20P3%20--%3E%20CMP%5B%22%E5%8A%A0%E9%80%9F%E9%83%BD%E4%BE%9D%E8%B5%96%E7%9B%AE%E6%A0%87%E6%A8%A1%E5%9E%8B%E9%AA%8C%E8%AF%81%22%5D%0A%20%20R3%20--%3E%20CMP%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>查表必须极便宜。若每步做一次向量检索，延迟可能高过小 Transformer 的一步 decode，投机就亏了。因此 REST 不用语义近邻，而用<strong>当前上下文的最长后缀在 datastore 里的精确出现</strong>。匹配是字符串级的，实现可以是后缀数组或等价索引，开销相对一次 LLM 前向可忽略。换来的限制也很硬：没在库里出现过的新颖续写，检索给不出好草稿。</p><h3 id="精确匹配不是语义检索" tabindex="-1">精确匹配不是语义检索 <a class="header-anchor" href="#精确匹配不是语义检索" aria-label="Permalink to &quot;精确匹配不是语义检索&quot;">​</a></h3><p>「A 函数的文档字符串」与「B 函数的文档字符串」在嵌入空间里可能很近，后缀却对不上。REST 不会把 A 的续写接到 B 上，除非字符级后缀碰巧相同。这避免了把错误 API 名字写进草稿树——那种错误往往在验证的很早位置就被拒，等于白付检索。它也意味着库必须覆盖目标域：用网页对话库去加速 HumanEval，命中率会明显低于用代码库。</p><p><span class="marginnote">REST 的检索发生在 token 序列上，分词器必须与目标模型一致。换词表等于换了一套后缀，旧 datastore 全部失效。这和参数化草稿要对齐词表是同一条约束，只是失败模式从「接受率低」变成「查不到」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>离线：把预训练语料或指令数据（论文里两种都试过）按目标分词器切成 token 序列，建后缀索引。库的粒度是整段文档的 token 流，不是句子嵌入。在线：设当前序列为 \\(s=(x_1,\\ldots,x_t)\\)。从 \\(s\\) 的末尾取越来越短的后缀，在索引里找精确命中；命中位置的后续若干 token 构成候选续写集合 \\(S\\)。</p><h3 id="从多条续写收到一棵-trie" tabindex="-1">从多条续写收到一棵 Trie <a class="header-anchor" href="#从多条续写收到一棵-trie" aria-label="Permalink to &quot;从多条续写收到一棵 Trie&quot;">​</a></h3><p>\\(S\\) 里常有大量重叠。把它们插入 Trie（前缀树），边上挂 token，节点上累计频次。低频枝剪掉，避免把验证预算浪费在只出现一两次的怪异续写上。<span class="marginnote">直觉类比：Trie 加频次剪枝就像中文输入法的候选栏——输入「今天」，候选按常用度排出「天气」「早上好」，冷门搭配根本不进列表。REST 相当于把整个语料库变成一本这样的联想词典：读到某处，翻出语料里所有人在同一位置的接法，按频率剪出几枝最可能的，交给目标模型批改。</span>然后按频次从根往下选出一组草稿 token，形成一棵待验证的树（或一条高频链）。验证用树注意力：每个候选只看见自己的前缀与已提交上下文，目标模型一次前向给出所有节点的 logits，再按投机规则接受最长合法前缀。<span class="marginnote">数字实例：检索出 20 条候选续写、每条约 5 个 token，全量验证要铺 100 个节点；按频次剪到 15–30 个节点的树，验证一次前向只比单 token 多两三成计算，却可能一口气接受 3–5 个 token——树多花一点、换来整段跳步，这正是树注意力值钱的地方。</span></p> \\[\\mathrm{query}(s)=\\arg\\max_{u\\ \\mathrm{suffix\\ of}\\ s}\\{\\lvert u\\rvert: u\\ \\text{在 datastore 中出现}\\} \\]<p>最长后缀优先：更长的上下文匹配通常给出更靠谱的续写；匹配不到足够长的后缀时退化为短模板，接受长度变短。</p>',10)),(E(),o(l,null,{default:e(()=>[i(t,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%BD%93%E5%89%8D%20token%20%E5%90%8E%E7%BC%80%22%5D%20--%3E%20I%5B%22%E5%90%8E%E7%BC%80%E6%95%B0%E7%BB%84%E7%B2%BE%E7%A1%AE%E6%9F%A5%E6%89%BE%22%5D%0A%20%20D%5B%22Datastore%22%5D%20--%3E%20I%0A%20%20I%20--%3E%20C%5B%22%E5%80%99%E9%80%89%E7%BB%AD%E5%86%99%E9%9B%86%E5%90%88%22%5D%0A%20%20C%20--%3E%20T%5B%22%E6%8C%89%E9%A2%91%E6%AC%A1%E5%89%AA%E6%9E%9D%E7%9A%84%20Trie%22%5D%0A%20%20T%20--%3E%20V%5B%22%E7%9B%AE%E6%A0%87%E6%A8%A1%E5%9E%8B%E6%A0%91%E9%AA%8C%E8%AF%81%22%5D%0A%20%20V%20--%3E%20A%7B%22%E6%8E%A5%E5%8F%97%E6%9C%80%E9%95%BF%E5%89%8D%E7%BC%80%22%7D%0A%20%20A%20--%3E%20S%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h3 id="库的选择决定加速比" tabindex="-1">库的选择决定加速比 <a class="header-anchor" href="#库的选择决定加速比" aria-label="Permalink to &quot;库的选择决定加速比&quot;">​</a></h3><p>代码生成用代码语料建库，对话用 ShareGPT 一类指令数据。论文在 7B / 13B、单 batch、A6000 上报告约 1.62–2.36×，代码侧通常高于开放对话——与 <a href="/llm/fu-lookahead">Lookahead</a> 挖掘可复用 n-gram 是同一方向，只是 REST 的 n-gram 来自静态库，Lookahead 来自本次 Jacobi 轨迹。库可以按租户分片：内部 API 文档进代码库，不要混进通用网页，以免高频但错误的网页短语污染 Trie。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>REST 的 \\(q\\) 是经验 n-gram 模型：在「看见这段后缀」的条件下，续写的频率估计。它没有深层的长程推理，却在局部句法与惯用搭配上往往足够像 \\(p\\)。验证保证不像的部分被拒，输出仍来自目标模型。加速来自「许多步的局部续写确实在库里」，而不是来自检索质量评分。</p><p>与参数草稿比，REST 的边际成本几乎是 CPU 上的索引查询，不占 GPU 算力，也不和目标抢 KV 带宽。这在 batch=1 的交互场景特别合适。连续批处理变大后，目标一步已经偏算力墙，检索再快也只省掉草稿那一项——而 REST 本来就没有草稿 GPU 时间，收益上限变成「树验证多出来的节点是否仍能被一次稍胖前向消化」。</p><p><span class="marginnote">Trie 上的频次是语料统计，不是目标模型的概率。高频续写在 \\(p\\) 里也可能是错的（过时 API、错误类型注解）。必须验证。把 REST 理解成「检索到就输出」会破坏无损，也会在评测上显得异常好或异常差。</span></p><h3 id="和-lookahead、specinfer-的分工" tabindex="-1">和 Lookahead、SpecInfer 的分工 <a class="header-anchor" href="#和-lookahead、specinfer-的分工" aria-label="Permalink to &quot;和 Lookahead、SpecInfer 的分工&quot;">​</a></h3><p>三条零或低训练的投机路：SpecInfer 用小模型采样多样性；Lookahead 用目标自己的并行猜测；REST 用静态语料的精确后缀。REST 对「库外」的新颖推理几乎没有帮助，但对样板极强。可以叠：检索树提供浅层高频枝，不够再让小模型补。工程上先单独测 REST，确认域内 n-gram 覆盖足够，再决定要不要养 SSM。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>datastore 要占磁盘与内存。代码库可以很小仍有用；开放网页要覆盖有用后缀，体积会涨。索引构建是一次性成本，目标分词器或模板一变必须重建。版权与污染：库若含评测集原文，加速数字会掺进「背到了 HumanEval」。应用侧应用训练允许的数据建库，并按租户隔离。</p><p>采样温度升高时，目标更常离开高频 n-gram，REST 的接受长度下降，这与 Lookahead 同类。结构化输出若有 JSON schema，应用约束解码剪枝 Trie，否则大量检索枝会在 schema 上提前非法。不要把 REST 写成 RAG：它不把检索文档拼进提示，只把续写 token 当草稿，提示里的证据仍然要靠调用方提供。</p><p><span class="marginnote">最长后缀匹配在重复标点、空白和三反引号代码围栏上会过度触发。需要对过短或过泛的后缀设最小长度，否则 Trie 被通用符号撑满，验证节点浪费在无信息枝上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>REST 用非参数 datastore 代替草稿模型：当前后缀精确匹配，续写进 Trie，目标模型一次树验证。</li><li>索引必须与目标分词器一致；库的域决定加速，代码通常高于开放对话。</li><li>论文在 7B/13B 单卡上约 1.62–2.36×；验证保持无损。</li><li>检索是字符串级 n-gram，不是语义 RAG；命中物必须再过目标 logits。</li><li>库外新颖生成帮助有限；温度升高或评测集泄漏都会扭曲数字。</li><li>出处：He et al., <em>REST: Retrieval-Based Speculative Decoding</em>，NAACL 2024；arXiv:2311.08252。</li></ul>',14))])}const _=s(B,[["render",p]]);export{u as __pageData,_ as default};
